class Solution:
    def widestSpacing(self, spots: List[int], sensors: int) -> int:
        s = sorted(spots)
        def fits(gap):
            placed, last = 1, s[0]
            for x in s[1:]:
                if x - last >= gap:
                    placed += 1
                    last = x
            return placed >= sensors
        gap = (s[-1] - s[0]) // (sensors - 1)
        while not fits(gap):
            gap -= 1
        return gap

