class Solution {
    public int widestSpacing(int[] spots, int sensors) {
        int[] s = spots.clone();
        Arrays.sort(s);
        int gap = (s[s.length - 1] - s[0]) / (sensors - 1);
        while (!fits(s, gap, sensors)) gap--;
        return gap;
    }

    private boolean fits(int[] s, int gap, int sensors) {
        int placed = 1, last = s[0];
        for (int i = 1; i < s.length; i++) if (s[i] - last >= gap) { placed++; last = s[i]; }
        return placed >= sensors;
    }
}

