static int cmpInt(const void* a, const void* b) {
    int p = *(const int*) a, q = *(const int*) b;
    return (p > q) - (p < q);
}

static bool fits(const int* s, int n, int gap, int sensors) {
    int placed = 1, last = s[0];
    for (int i = 1; i < n; i++) if (s[i] - last >= gap) { placed++; last = s[i]; }
